// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address someRewardToken) public {
        vm.assume(someRewardToken != address(0));
        // No staking or migration occurs, so balances remain zero.
        // After addReward, balanceOf(address(0)) should still be 0.
        c.addReward(someRewardToken);
        assertTrue(c.balanceOf(address(0)) == 0);
    }
}

